// ============================================================
// Student Dropout Prediction — Power BI Power Query M Scripts
// Source: artifacts/predictions.csv (generated by notebook)
// ============================================================

// ---- Table: Predictions (main fact table) -------------------
let
    Source       = Csv.Document(File.Contents("../artifacts/predictions.csv"),
                       [Delimiter=",", Encoding=65001, QuoteStyle=QuoteStyle.Csv]),
    promoted     = Table.PromoteHeaders(Source, [PromoteAllScalars=true]),
    typed        = Table.TransformColumnTypes(promoted, {
                       {"student_id",          Int64.Type},
                       {"age_at_enrollment",   Int64.Type},
                       {"gpa_1st_sem",         type number},
                       {"gpa_2nd_sem",         type number},
                       {"units_enrolled",      Int64.Type},
                       {"units_approved",      Int64.Type},
                       {"dropout_probability", type number},
                       {"gender",              type text},
                       {"enrollment_type",     type text},
                       {"scholarship",         type text},
                       {"actual_outcome",      type text},
                       {"predicted_outcome",   type text}
                   }),
    // add computed columns
    add_correct  = Table.AddColumn(typed, "CorrectPrediction",
                       each [actual_outcome] = [predicted_outcome],
                       type logical),
    add_risk     = Table.AddColumn(add_correct, "RiskBand",
                       each if [dropout_probability] >= 0.7 then "High Risk"
                            else if [dropout_probability] >= 0.4 then "Medium Risk"
                            else "Low Risk",
                       type text),
    add_gpa_d    = Table.AddColumn(add_risk, "GPADelta",
                       each [gpa_2nd_sem] - [gpa_1st_sem],
                       type number),
    add_approval = Table.AddColumn(add_gpa_d, "ApprovalRate",
                       each if [units_enrolled] > 0
                            then [units_approved] / [units_enrolled]
                            else null,
                       type number)
in
    add_approval


// ---- Table: Feature Importance (from notebook output) -------
let
    Source    = Csv.Document(File.Contents("../artifacts/feature_importance.csv"),
                    [Delimiter=",", Encoding=65001, QuoteStyle=QuoteStyle.Csv]),
    promoted  = Table.PromoteHeaders(Source, [PromoteAllScalars=true]),
    typed     = Table.TransformColumnTypes(promoted, {
                    {"feature",    type text},
                    {"importance", type number}
                }),
    sorted    = Table.Sort(typed, {{"importance", Order.Descending}}),
    add_rank  = Table.AddIndexColumn(sorted, "Rank", 1, 1, Int64.Type),
    top20     = Table.FirstN(add_rank, 20)
in
    top20


// ---- Table: MLflow Experiment Runs -------------------------
let
    Source   = Csv.Document(File.Contents("../artifacts/mlflow_runs.csv"),
                   [Delimiter=",", Encoding=65001, QuoteStyle=QuoteStyle.Csv]),
    promoted = Table.PromoteHeaders(Source, [PromoteAllScalars=true]),
    typed    = Table.TransformColumnTypes(promoted, {
                   {"run_id",        type text},
                   {"model_name",    type text},
                   {"accuracy",      type number},
                   {"recall",        type number},
                   {"precision",     type number},
                   {"f1",            type number},
                   {"roc_auc",       type number},
                   {"start_time",    type datetime},
                   {"duration_secs", type number}
               }),
    sorted   = Table.Sort(typed, {{"roc_auc", Order.Descending}})
in
    sorted
